// 1. Receber CSV como texto
const csv = $input.first().json.data;

if (typeof csv !== "string") {
  throw new Error("CSV não encontrado no campo data");
}

// 2. Converter CSV em objetos
const linhas = csv
  .replace(/^\uFEFF/, "")
  .trim()
  .split(/\r?\n/);

const colunas = linhas.shift()
  .split(",")
  .map(c => c.trim().toLowerCase());

const obrigatorias = ["perfil", "produto", "minimo", "rentabilidade"];
if (!obrigatorias.every(c => colunas.includes(c))) {
  throw new Error("CSV inválido: verifique a URL RAW e as colunas esperadas.");
}

const investimentos = linhas
  .filter(l => l.trim())
  .map(linha => {
    const valores = linha.split(",");
    const item = {};

    colunas.forEach((coluna, i) => {
      item[coluna] = valores[i]?.trim() ?? "";
    });

    return item;
  });

// 3. Formatar valores monetários
function moeda(valor) {
  const numero = Number(
    String(valor).replace(",", ".")
  );

  return numero.toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL"
  });
}

// 4. Proteger texto inserido no HTML
function escapar(valor) {
  return String(valor ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// 5. Criar linhas da tabela
const linhasHTML = investimentos.map(inv => {
  const cores = {
    conservador: "#15803d",
    moderado: "#b45309",
    arrojado: "#b91c1c"
  };

  const cor = cores[
    String(inv.perfil).toLowerCase()
  ] ?? "#475569";

  return `
    <tr>
      <td>
        <span style="color:${cor};font-weight:bold">
          ${escapar(inv.perfil)}
        </span>
      </td>
      <td>${escapar(inv.produto)}</td>
      <td>${moeda(inv.minimo)}</td>
      <td>${escapar(inv.rentabilidade)}</td>
    </tr>
  `;
}).join("");

// 6. Montar tabela HTML
const tabela_html = `
<html>
<head>
<meta charset="UTF-8">
</head>
<body style="font-family:Arial;background:#f1f5f9;padding:24px">

<h2 style="color:#0f172a">
  Assistente de Investimentos
</h2>

<p>Catálogo de opções por perfil de investidor</p>

<table style="
  width:100%;
  border-collapse:collapse;
  background:white;
  border-radius:8px;
  overflow:hidden;
">
  <thead>
    <tr style="background:#1e293b;color:white">
      <th style="padding:14px;text-align:left">Perfil</th>
      <th style="padding:14px;text-align:left">Investimento</th>
      <th style="padding:14px;text-align:left">Mínimo</th>
      <th style="padding:14px;text-align:left">Rentabilidade</th>
    </tr>
  </thead>
  <tbody>
    ${linhasHTML}
  </tbody>
</table>

<p style="font-size:12px;color:#64748b">
  Dados ilustrativos para fins educacionais.
  Rentabilidade não garantida.
</p>

</body>
</html>
`;

// 7. Manter estrutura compatível com o Merge
return [{
  json: {
    total_investimentos: investimentos.length,
    investimentos: investimentos,
    tabela_html: tabela_html
  }
}];

// Dados recebidos do Merge
const dados = $input.first().json;

const clientes = dados.body?.clientes ?? [];
const investimentos = dados.investimentos ?? [];

// Formatação monetária
function moeda(valor) {
  return Number(valor).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL"
  });
}

// Converter valores da base
function numero(valor) {
  if (typeof valor === "number") return valor;

  const texto = String(valor ?? "").trim()
    .replace(/R\$\s*/g, "");

  return Number(
    texto.includes(",")
      ? texto.replace(/\./g, "").replace(",", ".")
      : texto
  );
}

// Mensagens específicas por perfil
const explicacoes = {
  conservador:
    "Seu perfil prioriza segurança e previsibilidade. " +
    "É importante avaliar liquidez e riscos de cada produto.",

  moderado:
    "Seu perfil busca equilíbrio entre segurança " +
    "e potencial de rentabilidade, aceitando oscilações moderadas.",

  arrojado:
    "Seu perfil admite maiores oscilações em busca " +
    "de retornos potenciais mais elevados."
};

// Gerar mensagem individual
return clientes.map(cliente => {

  const perfil = String(cliente.perfil ?? "")
    .trim().toLowerCase();

  const saldo = numero(cliente.saldo);

  if (!Number.isFinite(saldo) || saldo < 0) {
    throw new Error("Saldo inválido: " + cliente.nome);
  }

  const opcoes = investimentos.filter(inv =>
    String(inv.perfil ?? "").trim().toLowerCase() === perfil &&
    Number.isFinite(numero(inv.minimo)) &&
    numero(inv.minimo) <= saldo
  );

  let mensagem =
    `Olá, ${cliente.nome}! 👋\n\n` +
    `Preparamos uma análise educacional com base ` +
    `no seu perfil de investidor.\n\n` +
    `📊 *Perfil:* ${cliente.perfil}\n` +
    `💰 *Saldo informado:* ${moeda(saldo)}\n\n` +
    `${explicacoes[perfil] ?? "Perfil não identificado."}\n\n`;

  if (opcoes.length > 0) {
    mensagem +=
      `📈 *Opções disponíveis na base:*\n\n`;

    opcoes.forEach((inv, i) => {
      mensagem +=
        `${i + 1}. *${inv.produto}*\n` +
        `   Aplicação mínima: ${moeda(numero(inv.minimo))}\n` +
        `   Rentabilidade ilustrativa: ${inv.rentabilidade}\n\n`;
    });
  } else {
    mensagem +=
      "No momento, nenhuma opção da base atende " +
      "ao seu perfil e ao valor mínimo de aplicação.\n\n";
  }

  mensagem +=
    "⚠️ *Importante:* As informações são educativas, " +
    "os rendimentos não são garantidos e esta mensagem " +
    "não constitui recomendação financeira individual.";

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo,
      investimentos: opcoes,
      mensagem,
      status: "MENSAGEM_GERADA"
    }
  };
});

// Receber todos os clientes do Code1
const clientes = $input.all();

// Formatar valores em reais
function moeda(valor) {
  return Number(valor).toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL"
  });
}

// Preparar um briefing para cada cliente
return clientes.map(item => {

  const cliente = item.json;

  const nome = String(cliente.nome ?? "").trim();
  const email = String(cliente.email ?? "").trim();
  const perfil = String(cliente.perfil ?? "").trim();
  const saldo = Number(cliente.saldo);

  const investimentos = Array.isArray(cliente.investimentos)
    ? cliente.investimentos
    : [];

  const lista = investimentos.map((inv, i) => {
    return (
      `${i + 1}. ${inv.produto}\n` +
      `Aplicação mínima: ${moeda(inv.minimo)}\n` +
      `Rentabilidade ilustrativa: ${inv.rentabilidade}`
    );
  }).join("\n\n");

  const briefing = `
Você é um assistente de comunicação financeira.

Crie um e-mail personalizado para este cliente.

NOME: ${nome}
EMAIL: ${email}
PERFIL: ${perfil}
SALDO: ${moeda(saldo)}

INVESTIMENTOS DISPONÍVEIS:
${lista || "Nenhuma opção compatível encontrada."}

REGRAS:
- Cumprimente o cliente pelo primeiro nome.
- Explique brevemente seu perfil.
- Utilize apenas os investimentos fornecidos.
- Não invente produtos ou rentabilidades.
- Não prometa lucros.
- Inclua aviso de conteúdo educacional.
- Não forneça recomendação financeira individual.

RETORNE APENAS JSON VÁLIDO:
{
  "assunto": "Assunto personalizado",
  "mensagem": "Corpo completo do e-mail"
}
`;

  return {
    json: {
      nome,
      email,
      perfil,
      saldo,
      investimentos,
      briefing,
      status: "PREPARADO_PARA_IA"
    }
  };
});

// Respostas do Gemini na iteração atual
const respostas = $input.all();

// Recuperar o cliente correspondente ao item atual
const cliente = $("Loop Over Items").item.json;

if (!cliente || !cliente.nome) {
  throw new Error("Cliente atual não encontrado no Loop.");
}

return respostas.map(item => {

  // Extrair texto do Gemini
  const texto =
    item.json.content?.parts
      ?.map(p => p.text ?? "")
      .join("\n") ??
    item.json.text ??
    "";

  const limpo = String(texto)
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  let resposta;

  try {
    resposta = JSON.parse(limpo);
  } catch {
    resposta = {
      assunto: `Informações sobre investimentos - ${cliente.nome}`,
      mensagem: limpo
    };
  }

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      investimentos: cliente.investimentos ?? [],
      assunto: resposta.assunto,
      mensagem: resposta.mensagem,
      status: "GERADO_COM_IA"
    }
  };
});

