return $input.all().map(item => ({
  json: {
    ...item.json,
    status_envio: "BLOQUEADO",
    motivo: "Destinatário não autorizado para envio (dados fictícios de laboratório)"
  }
}));

const resultados = $input.all().map(item => item.json);
const enviados = resultados.filter(r => r.status_envio === "ENVIADO");
const bloqueados = resultados.filter(r => r.status_envio === "BLOQUEADO");
const outros = resultados.filter(r => !["ENVIADO", "BLOQUEADO"].includes(r.status_envio));
return [{json:{
  status: "FINALIZADO",
  total_processados: resultados.length,
  emails_enviados: enviados.length,
  emails_bloqueados: bloqueados.length,
  outros_resultados: outros.length,
  clientes: resultados.map(r => ({
    nome: r.nome ?? null,
    email: r.email ?? null,
    perfil: r.perfil ?? null,
    status_envio: r.status_envio ?? "NAO_CLASSIFICADO",
    motivo: r.motivo ?? null,
    assunto: r.assunto ?? null
  })),
  data_relatorio: new Date().toISOString()
}}];

// Executado apenas depois que o Gmail confirmar a operação Send.
// Usa a iteração atual do Loop para evitar associar os dados à Ana em todos os itens.
const rodada = $("Loop Over Items").context.currentRunIndex;
const cliente = $("Code in JavaScript3").all(0, rodada)?.[0]?.json;
if (!cliente?.email) {
  throw new Error("Cliente da iteração atual não encontrado após o Gmail.");
}
return [{ json: {
  ...cliente,
  status_envio: "ENVIADO",
  gmail_message_id: $input.first().json.id ?? null,
  gmail_thread_id: $input.first().json.threadId ?? null
}}];
